package com.bank.flinkapi;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// LOW-LEVEL: process events one at a time with explicit keyed state + timers.
// Implements the custom rule: 3 txns within 30s AND 3rd > limit → alert.
class DataStreamApi {
    private static final Logger log = Logger.getLogger(DataStreamApi.class.getName());

    private final long limit;
    // Explicit per-key state: recent event timestamps (ValueState/ListState equivalent).
    private final Map<String, List<Long>> recentTimes = new HashMap<>();

    DataStreamApi(long limit) { this.limit = limit; }

    // Equivalent of KeyedProcessFunction.processElement — full control per event.
    void processElement(Transaction txn) {
        List<Long> times = recentTimes.computeIfAbsent(txn.accountId, k -> new ArrayList<>());
        times.add(txn.eventTimeSeconds);
        // Keep only events within the last 30 seconds (manual window via state + timer logic).
        times.removeIf(t -> txn.eventTimeSeconds - t > 30);
        log.fine(() -> "DataStream: " + txn.accountId + " has " + times.size() + " txns in last 30s");

        if (times.size() >= 3 && txn.amount > limit) {
            log.warning(() -> "CUSTOM RULE ALERT: " + txn.accountId + " made " + times.size()
                    + " txns in 30s and 3rd amount Rs." + txn.amount + " > limit Rs." + limit);
        }
    }
}
