package com.bank.flinkapi;

import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.logging.Logger;

// HIGH-LEVEL: declarative windowed aggregation. We model what the SQL optimizer computes.
class TableSqlApi {
    private static final Logger log = Logger.getLogger(TableSqlApi.class.getName());

    private final long windowSeconds;
    private final long flagThreshold;

    TableSqlApi(long windowSeconds, long flagThreshold) {
        this.windowSeconds = windowSeconds;
        this.flagThreshold = flagThreshold;
    }

    // Equivalent SQL:
    // SELECT account_id, TUMBLE_START(...), SUM(amount)
    // FROM txns GROUP BY account_id, TUMBLE(event_time, INTERVAL '5' MINUTE)
    void runWindowedAggregation(List<Transaction> txns) {
        log.info(() -> "Table/SQL: running declarative TUMBLE(" + windowSeconds + "s) SUM(amount) GROUP BY account");
        // Optimizer-managed windowed state (we compute it here for the demo).
        Map<String, Long> windowSums = new TreeMap<>();
        for (Transaction t : txns) {
            long windowStart = (t.eventTimeSeconds / windowSeconds) * windowSeconds;
            String key = t.accountId + "@win" + windowStart;
            windowSums.merge(key, t.amount, Long::sum);
        }
        windowSums.forEach((key, sum) -> {
            if (sum > flagThreshold) {
                log.warning(() -> "SQL FLAG: " + key + " total Rs." + sum + " > threshold Rs." + flagThreshold);
            } else {
                log.info(() -> "SQL window: " + key + " total Rs." + sum);
            }
        });
    }
}
