package com.bank.flinkapi;

import java.util.List;
import java.util.logging.Logger;

// Interop: Table ↔ DataStream, so SQL and low-level logic combine in ONE job.
class Converter {
    private static final Logger log = Logger.getLogger(Converter.class.getName());

    // tableEnv.toDataStream(table): hand a relational result to low-level processing.
    List<Transaction> toDataStream(List<Transaction> tableRows) {
        log.info(() -> "Converter: toDataStream — relational result now processed event-at-a-time");
        return tableRows;
    }

    // tableEnv.fromDataStream(stream): bring a stream back into the relational world.
    void fromDataStream(List<Transaction> streamRows) {
        log.info(() -> "Converter: fromDataStream — stream registered as a Table for SQL again");
    }
}
