package com.bank.flinkapi;

import java.util.List;
import java.util.logging.Logger;

public class ApiComparisonDemo {
    private static final Logger log = Logger.getLogger(ApiComparisonDemo.class.getName());

    public static void main(String[] args) {
        List<Transaction> txns = List.of(
            new Transaction("SAV2001", 20000, 0),
            new Transaction("SAV2001", 30000, 10),
            new Transaction("SAV2001", 90000, 25),   // 3rd within 30s, large → custom rule fires
            new Transaction("CUR3001", 40000, 5),
            new Transaction("CUR3001", 500000, 40)); // big → SQL flag

        // 1) Declarative windowed aggregation (Flink SQL style).
        log.info("=== Table API / Flink SQL (declarative) ===");
        new TableSqlApi(300, 400000).runWindowedAggregation(txns); // 5-min window = 300s

        // 2) Custom timer/state rule (DataStream API style).
        log.info("=== DataStream API (imperative, custom rule) ===");
        DataStreamApi ds = new DataStreamApi(75000);
        for (Transaction t : txns) ds.processElement(t);

        // 3) Interoperability: SQL result → DataStream for custom logic → back to SQL.
        log.info("=== Interop: Table ↔ DataStream in one job ===");
        Converter converter = new Converter();
        List<Transaction> handed = converter.toDataStream(txns);
        DataStreamApi ds2 = new DataStreamApi(75000);
        for (Transaction t : handed) ds2.processElement(t);
        converter.fromDataStream(handed);
    }
}
